void chief_ray_aiming() {
    auto _m = build();
    const auto &fields = _m->optical_spec->fov->fields;
    assertHasValue("aim.0.x - expected paraxial aiming", fields[0]->aim_info.has_value());
    assertClose("aim.0.x", 0.0, aim_or_nan(fields[0], 0), 1.0e-6);
    assertHasValue("aim.0.y - expected paraxial aiming", fields[0]->aim_info.has_value());
    assertClose("aim.0.y", 0.0, aim_or_nan(fields[0], 1), 1.0e-6);
    assertHasValue("aim.1.x - expected paraxial aiming", fields[1]->aim_info.has_value());
    assertClose("aim.1.x", 0.0, aim_or_nan(fields[1], 0), 1.0e-6);
    assertHasValue("aim.1.y - expected paraxial aiming", fields[1]->aim_info.has_value());
    assertClose("aim.1.y", 0.2695154184433682, aim_or_nan(fields[1], 1), 1.0e-6);
    assertHasValue("aim.2.x - expected paraxial aiming", fields[2]->aim_info.has_value());
    assertClose("aim.2.x", 0.0, aim_or_nan(fields[2], 0), 1.0e-6);
    assertHasValue("aim.2.y - expected paraxial aiming", fields[2]->aim_info.has_value());
    assertClose("aim.2.y", 0.8656855834279538, aim_or_nan(fields[2], 1), 1.0e-6);
}

